using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Fdc.Center.Persistence;
public sealed class CenterDbContext(DbContextOptions<CenterDbContext> options) : DbContext(options)
{
 protected override void OnModelCreating(ModelBuilder m)
 {
  m.Ignore<CenterRow>();
  m.Entity<StationReference>().ToTable("Station","catalog",t=>t.ExcludeFromMigrations()).HasKey(x=>x.Id);
  m.Entity<UnitReference>().ToTable("ManagementUnit","catalog",t=>t.ExcludeFromMigrations()).HasKey(x=>x.Id);
  m.Entity<SecurityEventReference>().ToTable("SecurityEvent","audit",t=>t.ExcludeFromMigrations()).HasKey(x=>x.Id);
  Add<StationSoeEvent>(m,"ops"); m.Entity<StationSoeEvent>().HasOne<IedDevice>().WithMany().HasForeignKey(x=>new{x.IedId,x.StationId}).HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict); m.Entity<StationSoeEvent>().HasIndex(x=>new{x.StationId,x.IedId,x.SourceEventId}).IsUnique(); m.Entity<StationSoeEvent>().HasIndex(x=>new{x.StationId,x.ReceivedAtUtc,x.Id}); Check<StationSoeEvent>(m,"Range","([Sequence] IS NULL OR [Sequence] BETWEEN 0 AND 65535) AND ([SubSequence] IS NULL OR [SubSequence] BETWEEN 0 AND 65535) AND ([ConfRev] IS NULL OR [ConfRev] BETWEEN 0 AND 4294967295)");
  Add<VoltageLevel>(m,"catalog"); Add<Manufacturer>(m,"catalog"); Add<DeviceModel>(m,"catalog"); Add<DeviceFirmware>(m,"catalog"); Add<CommunicationProfile>(m,"catalog"); Add<StationProfile>(m,"catalog"); Add<StationUnitHistory>(m,"catalog"); Add<Bay>(m,"catalog"); Add<Feeder>(m,"catalog"); Add<IedDevice>(m,"catalog");
  Add<CollectorRegistration>(m,"ops"); Add<CollectorIed>(m,"ops"); Add<CollectorHeartbeat>(m,"ops"); Add<CollectionJob>(m,"ops"); Add<CollectionAttempt>(m,"ops"); Add<ProcessingOutbox>(m,"ops"); Add<OperationalEvent>(m,"ops");
  Add<DisturbanceRecord>(m,"ingest"); Add<RecordFile>(m,"ingest"); Add<IngestionAttempt>(m,"ingest"); Add<RecordStatusHistory>(m,"ingest");
  Add<FaultEvent>(m,"ops"); Add<FaultEventRecord>(m,"ops"); Add<AnalysisAlgorithm>(m,"ops"); Add<AnalysisJob>(m,"ops"); Add<AnalysisResult>(m,"ops"); Add<AuditDelivery>(m,"audit"); Add<AuditCheckpoint>(m,"audit");
  m.Entity<VoltageLevel>().Property(x=>x.Kilovolts).HasPrecision(9,3); m.Entity<VoltageLevel>().HasIndex(x=>x.Kilovolts).IsUnique(); Check<VoltageLevel>(m,"PositiveKv","[Kilovolts]>0");
  m.Entity<Manufacturer>().HasIndex(x=>x.Code).IsUnique();
  Fk<DeviceModel,Manufacturer>(m,"ManufacturerId"); m.Entity<DeviceModel>().HasIndex(x=>new{x.ManufacturerId,x.Code}).IsUnique();
  Fk<DeviceFirmware,DeviceModel>(m,"DeviceModelId"); m.Entity<DeviceFirmware>().HasIndex(x=>new{x.DeviceModelId,x.Version}).IsUnique(); m.Entity<DeviceFirmware>().HasAlternateKey(x=>new{x.Id,x.DeviceModelId});
  m.Entity<CommunicationProfile>().HasIndex(x=>x.Code).IsUnique(); Check<CommunicationProfile>(m,"Protocol","[Protocol] IN ('IEC61850','SFTP','HTTPS') AND [Port] BETWEEN 1 AND 65535");
  Station<StationProfile>(m); Fk<StationProfile,VoltageLevel>(m,"VoltageLevelId"); m.Entity<StationProfile>().HasIndex(x=>x.StationId).IsUnique();
  Station<StationUnitHistory>(m); Fk<StationUnitHistory,UnitReference>(m,"ManagementUnitId"); Check<StationUnitHistory>(m,"Validity","[ValidUntilUtc] IS NULL OR [ValidUntilUtc]>[ValidFromUtc]"); m.Entity<StationUnitHistory>().HasIndex(x=>x.StationId).IsUnique().HasFilter("[ValidUntilUtc] IS NULL");
  Station<Bay>(m); Station<Feeder>(m); m.Entity<Bay>().HasAlternateKey(x=>new{x.Id,x.StationId}); m.Entity<Feeder>().HasAlternateKey(x=>new{x.Id,x.StationId}); m.Entity<Bay>().HasIndex(x=>new{x.StationId,x.Code}).IsUnique(); m.Entity<Feeder>().HasIndex(x=>new{x.StationId,x.Code}).IsUnique();
  Station<IedDevice>(m); m.Entity<IedDevice>().HasAlternateKey(x=>new{x.Id,x.StationId}); m.Entity<IedDevice>().HasIndex(x=>new{x.StationId,x.Code}).IsUnique();
  m.Entity<IedDevice>().HasOne<Bay>().WithMany().HasForeignKey(x=>new{x.BayId,x.StationId}).HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict);
  m.Entity<IedDevice>().HasOne<Feeder>().WithMany().HasForeignKey(x=>new{x.FeederId,x.StationId}).HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict);
  Fk<IedDevice,DeviceModel>(m,"DeviceModelId"); Fk<IedDevice,CommunicationProfile>(m,"CommunicationProfileId"); m.Entity<IedDevice>().HasOne<DeviceFirmware>().WithMany().HasForeignKey(x=>new{x.FirmwareId,x.DeviceModelId}).HasPrincipalKey(x=>new{x.Id,x.DeviceModelId}).OnDelete(DeleteBehavior.Restrict); Check<IedDevice>(m,"FirmwareModel","[FirmwareId] IS NULL OR [DeviceModelId] IS NOT NULL");
  Station<CollectorRegistration>(m); m.Entity<CollectorRegistration>().HasIndex(x=>x.Code).IsUnique(); m.Entity<CollectorRegistration>().HasAlternateKey(x=>new{x.Id,x.StationId}); Check<CollectorRegistration>(m,"Config","[ConfigurationVersion]>0 AND [BindingStatus] IN ('Pending','Bound','Revoked')");
  Collector<CollectorIed>(m); m.Entity<CollectorIed>().HasOne<IedDevice>().WithMany().HasForeignKey(x=>new{x.IedId,x.StationId}).HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict); m.Entity<CollectorIed>().HasAlternateKey(x=>new{x.CollectorId,x.IedId,x.StationId});
  Collector<CollectorHeartbeat>(m); Check<CollectorHeartbeat>(m,"Queue","[QueueDepth]>=0 AND [Status] IN ('Healthy','Degraded','Offline','Unknown')"); m.Entity<CollectorHeartbeat>().HasIndex(x=>new{x.CollectorId,x.ReceivedAtUtc});
  Assignment<CollectionJob>(m); Check<CollectionJob>(m,"State","[State] IN ('Pending','Running','Completed','Failed','Cancelled')"); m.Entity<CollectionJob>().HasIndex(x=>new{x.State,x.NextRunAtUtc});
  Fk<CollectionAttempt,CollectionJob>(m,"JobId"); m.Entity<CollectionAttempt>().HasIndex(x=>new{x.JobId,x.Number}).IsUnique(); Check<CollectionAttempt>(m,"Attempt","[Number]>0 AND [Outcome] IN ('Succeeded','Failed','Cancelled')");
  m.Entity<DisturbanceRecord>().Property(x=>x.ManifestSnapshotJson).HasColumnType("nvarchar(max)").HasMaxLength(65536); Check<DisturbanceRecord>(m,"ManifestSnapshot","[ManifestSnapshotJson] IS NULL OR (ISJSON([ManifestSnapshotJson])=1 AND DATALENGTH([ManifestSnapshotJson])<=131072)");
  Assignment<DisturbanceRecord>(m); m.Entity<DisturbanceRecord>().HasAlternateKey(x=>new{x.Id,x.StationId}); m.Entity<DisturbanceRecord>().HasIndex(x=>new{x.StationId,x.IedId,x.ManifestId}).IsUnique(); m.Entity<DisturbanceRecord>().HasIndex(x=>new{x.StationId,x.EventAtUtc,x.Id}); m.Entity<DisturbanceRecord>().HasIndex(x=>new{x.StationId,x.State,x.CreatedAtUtc}); Hash<DisturbanceRecord>(m,"ManifestId"); Hash<DisturbanceRecord>(m,"ManifestSha256"); Check<DisturbanceRecord>(m,"State","[State] IN ('MetadataAccepted','Validated','Quarantined','Processing','Processed','Failed','Retained')");
  Record<RecordFile>(m); Record<IngestionAttempt>(m); Record<RecordStatusHistory>(m); Record<ProcessingOutbox>(m);
  m.Entity<RecordFile>().Property(x=>x.Name).UseCollation("Latin1_General_100_CI_AS"); m.Entity<RecordFile>().HasIndex(x=>new{x.RecordId,x.Name}).IsUnique(); m.Entity<RecordFile>().HasIndex(x=>x.Sha256); Hash<RecordFile>(m,"Sha256"); Check<RecordFile>(m,"File","[SizeBytes]>=0 AND [Extension] IN ('.cfg','.dat','.hdr','.inf') AND [ValidationStatus] IN ('Pending','Verified','Rejected') AND [Name] NOT LIKE '%/%' AND [Name] NOT LIKE '%\\%' AND [Name] NOT LIKE '%:%'"); Check<RecordFile>(m,"ObjectKey","[StorageObjectKey] NOT LIKE '%..%' AND [StorageObjectKey] NOT LIKE '%:%' AND LEFT([StorageObjectKey],1)<>'/' AND [StorageObjectKey] NOT LIKE '%\\%'");
  m.Entity<IngestionAttempt>().HasIndex(x=>new{x.RecordId,x.Number}).IsUnique(); Check<IngestionAttempt>(m,"Attempt","[Number]>0 AND [Outcome] IN ('Accepted','Duplicate','Rejected','Failed')"); m.Entity<RecordStatusHistory>().HasIndex(x=>new{x.RecordId,x.CreatedAtUtc});
  m.Entity<ProcessingOutbox>().HasIndex(x=>new{x.RecordId,x.Kind}).IsUnique(); m.Entity<ProcessingOutbox>().HasIndex(x=>new{x.State,x.AvailableAtUtc}); Check<ProcessingOutbox>(m,"Queue","[Attempts]>=0 AND [State] IN ('Pending','Leased','Completed','Failed') AND (([LeaseUntilUtc] IS NULL AND [LeaseOwner] IS NULL) OR ([LeaseUntilUtc] IS NOT NULL AND [LeaseOwner] IS NOT NULL))");
  Check<FaultEvent>(m,"AnalysisState","[AnalysisStatus] IN ('NotImplemented','Pending','Completed','Failed')"); Check<AnalysisJob>(m,"State","[State] IN ('NotImplemented','Pending','Running','Completed','Failed')"); Check<AnalysisResult>(m,"State","[Status] IN ('NotImplemented','Completed','Failed')");
  Station<FaultEvent>(m); m.Entity<FaultEvent>().HasAlternateKey(x=>new{x.Id,x.StationId}); m.Entity<FaultEvent>().HasIndex(x=>new{x.StationId,x.EventAtUtc,x.Id}); Record<FaultEventRecord>(m); Event<FaultEventRecord>(m); m.Entity<FaultEventRecord>().HasIndex(x=>new{x.FaultEventId,x.RecordId}).IsUnique();
  m.Entity<AnalysisAlgorithm>().HasIndex(x=>new{x.Code,x.Version}).IsUnique(); Event<AnalysisJob>(m); Fk<AnalysisJob,AnalysisAlgorithm>(m,"AlgorithmId"); Fk<AnalysisResult,AnalysisJob>(m,"JobId"); m.Entity<AnalysisResult>().HasIndex(x=>x.JobId).IsUnique(); Check<AnalysisResult>(m,"Json","([ResultJson] IS NULL OR ISJSON([ResultJson])=1) AND ([Status]<>'NotImplemented' OR [ResultJson] IS NULL)");
  Station<OperationalEvent>(m); Collector<OperationalEvent>(m); Fk<AuditDelivery,SecurityEventReference>(m,"EventId"); Check<AuditDelivery>(m,"Attempt","[Attempt]>0 AND [State] IN ('Pending','Delivered','Failed')"); m.Entity<AuditDelivery>().HasIndex(x=>new{x.EventId,x.Attempt}).IsUnique(); Hash<AuditCheckpoint>(m,"ContentSha256"); Check<AuditCheckpoint>(m,"Status","[Status] IN ('Unverified','Verified','Rejected')");
 }
 private static void Add<T>(ModelBuilder m,string schema) where T:CenterRow
 {
  var b=m.Entity<T>(); b.HasBaseType((Type?)null); b.ToTable(typeof(T).Name,schema,t=>t.HasCheckConstraint("CK_"+typeof(T).Name+"_Utc","DATEPART(TZOFFSET,[CreatedAtUtc])=0 AND ([UpdatedAtUtc] IS NULL OR DATEPART(TZOFFSET,[UpdatedAtUtc])=0)")); b.HasKey(x=>x.Id); b.Property(x=>x.Id).ValueGeneratedNever(); b.Property(x=>x.RowVersion).IsRowVersion();
  foreach(var p in b.Metadata.GetProperties().Where(p=>(p.ClrType==typeof(DateTimeOffset)||p.ClrType==typeof(DateTimeOffset?)) && p.Name!="CreatedAtUtc" && p.Name!="UpdatedAtUtc")) b.ToTable(t=>t.HasCheckConstraint("CK_"+typeof(T).Name+"_Utc_"+p.Name,$"[{p.Name}] IS NULL OR DATEPART(TZOFFSET,[{p.Name}])=0"));
  foreach(var p in b.Metadata.GetProperties().Where(p=>p.ClrType==typeof(string))) {p.SetMaxLength(p.Name=="ResultJson"?4000:p.Name.Contains("Identity")||p.Name.Contains("ObjectKey")?512:200); if(!p.IsNullable) b.ToTable(t=>t.HasCheckConstraint("CK_"+typeof(T).Name+"_"+p.Name+"_Required",$"LEN([{p.Name}])>0"));}
 }
 private static void Fk<T,P>(ModelBuilder m,string property) where T:class where P:class =>m.Entity<T>().HasOne<P>().WithMany().HasForeignKey(property).OnDelete(DeleteBehavior.Restrict);
 private static void Station<T>(ModelBuilder m) where T:class =>Fk<T,StationReference>(m,"StationId");
 private static void Collector<T>(ModelBuilder m) where T:class =>m.Entity<T>().HasOne<CollectorRegistration>().WithMany().HasForeignKey("CollectorId","StationId").HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict);
 private static void Assignment<T>(ModelBuilder m) where T:class =>m.Entity<T>().HasOne<CollectorIed>().WithMany().HasForeignKey("CollectorId","IedId","StationId").HasPrincipalKey(x=>new{x.CollectorId,x.IedId,x.StationId}).OnDelete(DeleteBehavior.Restrict);
 private static void Record<T>(ModelBuilder m) where T:class =>m.Entity<T>().HasOne<DisturbanceRecord>().WithMany().HasForeignKey("RecordId","StationId").HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict);
 private static void Event<T>(ModelBuilder m) where T:class =>m.Entity<T>().HasOne<FaultEvent>().WithMany().HasForeignKey("FaultEventId","StationId").HasPrincipalKey(x=>new{x.Id,x.StationId}).OnDelete(DeleteBehavior.Restrict);
 private static void Check<T>(ModelBuilder m,string suffix,string sql) where T:class =>m.Entity<T>().ToTable(t=>t.HasCheckConstraint("CK_"+typeof(T).Name+"_"+suffix,sql));
 private static void Hash<T>(ModelBuilder m,string column) where T:class {m.Entity<T>().Property<string>(column).HasMaxLength(64).UseCollation("Latin1_General_100_BIN2");Check<T>(m,column,$"LEN([{column}])=64 AND [{column}] NOT LIKE '%[^0-9a-f]%'");}
}
